from html.parser import HTMLParser

class ProductParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.products = []
        self.field = None

    def handle_starttag(self, tag, attrs):
        classes = (dict(attrs).get("class") or "").split()
        if tag == "div" and "product" in classes:
            self.products.append({})
        elif self.products and ("name" in classes or "price" in classes):
            self.field = "name" if "name" in classes else "price"

    def handle_endtag(self, tag):
        self.field = None

    def handle_data(self, data):
        if self.field and data.strip():
            self.products[-1][self.field] = data.strip()

def extract_products(html: str) -> list[dict]:
    parser = ProductParser()
    parser.feed(html)
    return [{"name": p["name"], "price": int(p["price"].replace("₹", "").replace(",", ""))}
            for p in parser.products]

print(extract_products('<div class="product"><h2 class="name">Masala Chai</h2><span class="price">₹180</span></div>'))

from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

class HrefCollector(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hrefs = []

    def handle_starttag(self, tag, attrs):
        href = dict(attrs).get("href")
        if tag == "a" and href:
            self.hrefs.append(href)

def external_links(html: str, base_url: str) -> list[str]:
    collector = HrefCollector()
    collector.feed(html)
    home = urlparse(base_url).netloc
    found = set()
    for href in collector.hrefs:
        parts = urlparse(urljoin(base_url, href))
        if parts.scheme in ("http", "https") and parts.netloc != home:
            found.add(parts.geturl())
    return sorted(found)

print(external_links('<a href="https://partner.example/cups">Cups</a>', "https://chaishop.example/"))
